#!/usr/bin/env sh
# Statusline renderer for Claude Code — SUPERSET of ~/.claude/joyia-statusline.sh.
#
# WHY A SEPARATE FILE: joyia-statusline.sh is INSTALLED/REGENERATED by
# `joyia agent --setup`, so edits there are not durable. This file reproduces
# every field that renderer showed (JoyIA mark, model, ctx %, cost, git branch,
# worktree, +adds/-dels) and adds the fields the vendored one lacked. The
# vendored script is left untouched on disk as a fallback/reference.
#
# Called by scripts/cost-ledger-capture.sh with the statusLine JSON on stdin.
#
# Line 1 (one concise line, fixed-width-ish scalars only):
#   JoyIA · <model> <effort> · ctx <tokens> <pct>% · 5h <pct>% · 7d <pct>%
# Line 2 (the SPEND line: both dollar figures together, today first since that is the one
# measured against the cap. Its own line since 0.5.1 -- sharing line 1 overflowed one
# terminal width and wrapped):
#   session $<cost> · today: $<spent>/$<cap> gw
# Line 3 (variable-length names, which can be long, + the previous git fields):
#   <dir basename> · <branch> · <worktree> · +<added>/-<removed>
#
# The model's context-window suffix is abbreviated for width: "Opus 5 (1M context)"
# renders as "Opus 5 (1M)".
#
# DELIBERATELY OMITTED (2026-08-26, user call): the context WINDOW SIZE (already
# implied by the model name, e.g. "Opus 5 (1M)") and the per-request token
# breakdown (fresh / cache-read / cache-write) -- ctx alone is the signal wanted,
# the rest was noise. The jq pass no longer extracts them at all.
#
# Every field is optional: anything missing or null is dropped, not printed as
# "null" or "0". No network calls; one jq pass; git is best-effort and local.

# Argument handling comes BEFORE the stdin read. This script's normal input is the
# statusLine JSON on stdin, so a user probing it with --help would otherwise block on an
# empty terminal or render a line and have that read as help output.
case "${1:-}" in
  -h|--help)
    cat <<'USAGE'
statusline-render.sh — render the Claude Code status line.

Reads the statusLine JSON payload on stdin and prints up to three lines:

  JoyIA · <model> <effort> · ctx <tokens> <pct>% · 5h <pct>% · 7d <pct>%
  session $<cost> · today: $<billed>/$<cap> gw · local saved $<saved>
  <dir basename> · <branch> · <worktree> · +<added>/-<removed>

Usage:
  <statusline JSON> | statusline-render.sh
  statusline-render.sh --help

The budget line comes from the sibling `cost-tracker` CLI and is on the GATEWAY axis: the
markup is already applied, so both figures match the cap the gateway's refusal quotes.

Every field is optional — anything missing or null is dropped rather than printed as
"null" or "0". No network calls; git is best-effort and local. Always exits 0 so a
rendering problem can never break the status line.

Environment:
  COST_TRACKER_STATUSLINE=0   omit the budget line entirely
  COST_TRACKER_RAM_CAP_GB     memory ceiling the ram segment is measured against
                              (default 103.9, the measured Metal wired cap on a
                              128 GB M4 Max — it is NOT installed RAM)
  COST_TRACKER_RAM_CMD        override the memory reader; must print
                              "<wired-gb> <total-gb>". Intended for tests, so the
                              suite never depends on real machine memory.

The ram segment appears ONLY when ANTHROPIC_BASE_URL points at loopback (a local
inference session). It reports WIRED memory against the cap, because ps RSS
understates MLX pressure by roughly 7x, and colours green/yellow/red as the
ceiling approaches. It is deliberately absent on cloud sessions.
USAGE
    exit 0
    ;;
  -?*)
    printf 'statusline-render.sh: unrecognised option: %s\n' "$1" >&2
    printf "Try 'statusline-render.sh --help'.\n" >&2
    exit 2
    ;;
esac

LC_ALL=C
export LC_ALL

INPUT="$(cat)"

# --- extract: ONE jq pass, US-delimited, empty string for missing/null --------
# Delimiter is \037 (ASCII US), NOT tab: tab is an IFS *whitespace* character, so
# `read` collapses runs of tabs and every field after an absent one shifts left
# (observed: a missing .effort.level silently pushed the directory into EFFORT).
# \037 is non-whitespace, so empty fields are preserved exactly.
# Field order must match the `read` below.
FIELDS=""
if command -v jq >/dev/null 2>&1; then
  FIELDS=$(printf '%s' "$INPUT" | jq -r '
    def s: if . == null then "" else (.|tostring) end;
    def pct: if . == null then "" else (.|round|tostring) end;
    [ (.model.display_name          // "Claude")
    , (.effort.level                // null      | s)
    , (.workspace.current_dir       // .cwd // "" )
    , (.context_window.total_input_tokens   // null | s)
    , (.context_window.used_percentage      // null | pct)
    , (.cost.total_cost_usd         // null      | s)
    , (.cost.total_lines_added      // 0         | s)
    , (.cost.total_lines_removed    // 0         | s)
    , (.rate_limits.five_hour.used_percentage // null | pct)
    , (.rate_limits.seven_day.used_percentage // null | pct)
    ] | join("\u001f")
  ' 2>/dev/null || true)
fi

MODEL=Claude; EFFORT=; CWD=; CTX_CUR=; CTX_PCT=
COST=; ADD=0; DEL=0; FIVEH=; SEVEND=
if [ -n "$FIELDS" ]; then
  # shellcheck disable=SC2162
  IFS="$(printf '\037')" read MODEL EFFORT CWD CTX_CUR CTX_PCT \
                COST ADD DEL FIVEH SEVEND <<EOF
$FIELDS
EOF
fi
[ -n "$MODEL" ] || MODEL=Claude
[ -n "$CWD" ] || CWD="$PWD"
case "$ADD" in ''|*[!0-9]*) ADD=0 ;; esac
case "$DEL" in ''|*[!0-9]*) DEL=0 ;; esac
DIRBASE=$(basename "$CWD" 2>/dev/null || printf '%s' "$CWD")

# Abbreviate the model's context-window suffix: "Opus 5 (1M context)" -> "Opus 5 (1M)".
# The word "context" is pure padding here — nothing else on the line could be measured in
# M, and the whole segment exists to say which window this session has. Cheap 8 columns on
# the line that has the least room to spare. Substitution only, so a display name without
# the suffix is passed through untouched.
MODEL=$(printf '%s' "$MODEL" | sed 's/ context)/)/')

# Cost -> 2dp. C locale forced above so "1.2345" parses under de_DE.
COST_FMT=
if [ -n "$COST" ]; then
  COST_FMT=$(printf '%.2f' "$COST" 2>/dev/null || printf '%s' "$COST")
fi

# --- git (best-effort, local only) -------------------------------------------
BRANCH=; WORKTREE=
if command -v git >/dev/null 2>&1; then
  BRANCH=$(git -C "$CWD" branch --show-current 2>/dev/null || true)
  TOPLEVEL=$(git -C "$CWD" rev-parse --show-toplevel 2>/dev/null || true)
  [ -n "$TOPLEVEL" ] && WORKTREE=$(basename "$TOPLEVEL")
fi

# --- render -------------------------------------------------------------------
DIM=$(printf '\033[2m');    BOLD=$(printf '\033[1m')
RESET=$(printf '\033[0m');  CYAN=$(printf '\033[36m')
YELLOW=$(printf '\033[33m');GREEN=$(printf '\033[32m')
RED=$(printf '\033[31m');   MAGENTA=$(printf '\033[35m')
BLUE=$(printf '\033[34m')
SEP="${DIM} · ${RESET}"

LINE1="${BOLD}${BLUE}JoyIA${RESET}${SEP}${BOLD}${MODEL}${RESET}"
[ -n "$EFFORT" ] && LINE1="${LINE1} ${DIM}${EFFORT}${RESET}"

# ctx: absolute input tokens + percentage. The window SIZE is intentionally not
# shown -- the model name already carries it. Each half is independent so a
# payload with only one of them still renders something useful.
CTXSTR=
if [ -n "$CTX_CUR" ]; then
  CTXSTR="ctx ${CTX_CUR}"
fi
if [ -n "$CTX_PCT" ]; then
  if [ -n "$CTXSTR" ]; then CTXSTR="${CTXSTR} ${CTX_PCT}%"; else CTXSTR="ctx ${CTX_PCT}%"; fi
fi
[ -n "$CTXSTR" ] && LINE1="${LINE1}${SEP}${CYAN}${CTXSTR}${RESET}"

# --- the TODAY segment (cost-tracker) ----------------------------------------
# Two dollar figures on one line MUST each name their axis, or this reproduces the
# mislabel bug the plugin exists to prevent: the renderer's own figure is the
# SESSION LIFETIME, while the segment below is TODAY ACROSS ALL SESSIONS. So the
# lifetime figure is prefixed "session" only when the today segment is actually
# present — when it is alone there is nothing to confuse it with, and the label
# would just be noise.
#
# Opt out with COST_TRACKER_STATUSLINE=0. --fast keeps this off the history log and
# reads savings from the derived rollup, so it adds ~50ms rather than ~190ms. Wrapped
# so that a failure loses the segment and nothing else: this file must always exit 0.
TODAY_SEG=
if [ "${COST_TRACKER_STATUSLINE:-1}" != "0" ]; then
    # RESOLVE $0 THROUGH SYMLINKS FIRST. In the wired setup this file is reached as
    # ~/.claude/scripts/statusline-render.sh, a symlink into the plugin — so a plain
    # dirname "$0" looks for the CLI in ~/.claude/scripts, where it is not, and the
    # segment silently never appeared. Found end-to-end, not by the unit tests, which
    # invoked the renderer directly in the repo where the sibling happens to be there.
    # No readlink -f: it is not portable to every /bin/sh this may run under.
    CT_SELF="$0"
    CT_HOPS=0
    while [ -L "$CT_SELF" ] && [ "$CT_HOPS" -lt 10 ]; do
        CT_LINK="$(readlink "$CT_SELF")"
        case "$CT_LINK" in
            /*) CT_SELF="$CT_LINK" ;;
            *)  CT_SELF="$(dirname "$CT_SELF")/$CT_LINK" ;;
        esac
        CT_HOPS=$((CT_HOPS + 1))
    done
    CT_BIN="$(dirname "$CT_SELF")/cost-tracker"
    if [ -x "$CT_BIN" ]; then
        TODAY_SEG=$(python3 "$CT_BIN" statusline --fast 2>/dev/null | head -1) || TODAY_SEG=
    fi
fi

# --- LOCAL-SESSION MEMORY PRESSURE (the D-METAL-CAP instrument) ----------------------
# WHY THIS EXISTS, and why it is not cosmetic: on this class of machine an MLX local
# session dies by OOM against a Metal wired-memory ceiling well below installed RAM
# (~103.9 GB on a 128 GB M4 Max). Before this segment there was NO live reading of that
# anywhere, so the ceiling was invisible until the session was already dead — measured
# 2026-09-15, when a dispatch was fired at a local endpoint with no preflight because
# neither party could see the number.
#
# ps RSS IS THE WRONG NUMBER — it understates MLX pressure by roughly 7x, because the
# weights are Metal allocations, not ordinary resident pages. WIRED memory is the figure
# that tracks the ceiling that actually refuses work, so wired-vs-cap is what renders.
#
# GATED ON THE ENDPOINT, NEVER ON CLAUDE_IS_LOCAL: that flag is exported by the local
# launcher and LEAKS into a later gateway `claude` from the same shell, which would paint
# a paid cloud session with a local instrument. ANTHROPIC_BASE_URL pointing at loopback is
# the honest signal, and it is per-process.
#
# Absent on a cloud session by design: a remote session has no local weights, so the
# number would be noise on the one line with least room to spare.
RAM_SEG=
case "${ANTHROPIC_BASE_URL:-}" in
  *localhost*|*127.0.0.1*|*'[::1]'*)
    # Injectable for tests. A suite that reads REAL machine memory passes or fails by luck
    # and cannot exercise the near-cap branch at all, so the reader is overridable and the
    # tests drive it with fixed values instead of whatever this laptop happens to be doing.
    if [ -n "${COST_TRACKER_RAM_CMD:-}" ]; then
      RAM_RAW=$($COST_TRACKER_RAM_CMD 2>/dev/null)
    elif [ "$(uname -s 2>/dev/null)" = "Darwin" ] && command -v vm_stat >/dev/null 2>&1; then
      # Same derivation as local-agents' la-ram-preflight.sh (wired pages x page size),
      # deliberately not re-invented: two different numbers for "wired" would be worse
      # than none. Page size is read from vm_stat's own header rather than assumed 16k.
      RAM_RAW=$(vm_stat 2>/dev/null | awk -v tot="$(sysctl -n hw.memsize 2>/dev/null)" '
        /page size of/{gsub(/[^0-9]/,"",$0); ps=$0}
        /Pages wired down/{gsub(/[^0-9]/,"",$4); w=$4}
        END{ if (ps>0 && w>0 && tot>0) printf "%.1f %.1f", w*ps/1073741824, tot/1073741824 }')
    fi
    if [ -n "${RAM_RAW:-}" ]; then
      # shellcheck disable=SC2162
      read RAM_WIRED RAM_TOTAL <<EOF2
$RAM_RAW
EOF2
      # The cap is what refuses work, and it is NOT installed RAM. Overridable because it is
      # machine-specific; the default is the measured D-METAL-CAP for this 128 GB M4 Max.
      RAM_CAP="${COST_TRACKER_RAM_CAP_GB:-103.9}"
      case "$RAM_WIRED" in ''|*[!0-9.,]*) RAM_WIRED= ;; esac
      if [ -n "$RAM_WIRED" ]; then
        # Render wired AGAINST the cap: "wired 96 GB" means nothing without the ceiling
        # beside it, which is the whole point of the instrument.
        RAM_PCT=$(LC_ALL=C awk -v w="$RAM_WIRED" -v c="$RAM_CAP" 'BEGIN{ if (c>0) printf "%.0f", (w/c)*100 }' 2>/dev/null)
        RAM_SEG="ram ${RAM_WIRED}/${RAM_CAP}G"
        [ -n "$RAM_PCT" ] && RAM_SEG="${RAM_SEG} ${RAM_PCT}%"
      fi
    fi
    ;;
esac

# The RAM instrument sits on line 1 next to ctx, and ESCALATES IN COLOUR as it approaches the
# ceiling: green below 70% of cap, yellow from 70%, bold red from 90% — because a number you
# have to read and compare is a number you will miss while working, and the whole purpose is
# to see the cliff coming. Colour is redundant with the digits, never the only signal.
if [ -n "$RAM_SEG" ]; then
  RAM_COLOUR="$GREEN"
  if [ -n "${RAM_PCT:-}" ]; then
    if   [ "$RAM_PCT" -ge 90 ] 2>/dev/null; then RAM_COLOUR="${BOLD}${RED}"
    elif [ "$RAM_PCT" -ge 70 ] 2>/dev/null; then RAM_COLOUR="$YELLOW"
    fi
  fi
  LINE1="${LINE1}${SEP}${RAM_COLOUR}${RAM_SEG}${RESET}"
fi

[ -n "$FIVEH" ]  && LINE1="${LINE1}${SEP}${MAGENTA}5h ${FIVEH}%${RESET}"
[ -n "$SEVEND" ] && LINE1="${LINE1}${SEP}${MAGENTA}7d ${SEVEND}%${RESET}"

# --- the SPEND line ----------------------------------------------------------------
# Both dollar figures live together on their own line: SESSION first, TODAY second.
# EMPHASIS IS WEIGHT, NOT POSITION — today is the figure that matters (it is the one measured
# against the cap) so it is BOLD while the session lifetime is DIMMED, and it reads as primary
# from either position. Leading with it was tried and was not the lever: two figures in the
# same colour read as equal however they are ordered, so dimming the secondary one is what
# separates them. That decoupling lets the order follow reading habit — the session you are
# in, then the day it sits inside — at no cost in prominence.
# A lone session figure is NOT dimmed: it is not secondary to anything.
# They belong on the SAME line precisely because they are
# comparable quantities — separating them invites reading whichever is visible as "the"
# spend, which is the mislabel this plugin exists to prevent. Keeping them off line 1 is
# what stops the overflow that made this a separate line in the first place (108 columns,
# wrapped); keeping them off the dir/branch line is what stops it coming back, since that
# line is variable-length per project.
#
# The "session" prefix is still conditional on the today segment being present: with one
# figure alone there is nothing to confuse it with and the label would be noise.
# WEIGHT, not order, carries the emphasis: today is BOLD yellow and the session lifetime is
# DIMMED beside it. The two figures read at a glance in the right priority without reordering
# them or padding either with extra words, and dimming the secondary one is what makes the
# primary stand out — brightening both would leave them equal again. When the session figure
# stands ALONE it is not secondary to anything, so it keeps normal weight.
TODAY_LINE=
if [ -n "$COST_FMT" ]; then
    if [ -n "$TODAY_SEG" ]; then
        TODAY_LINE="${DIM}${YELLOW}session \$${COST_FMT}${RESET}"
    else
        TODAY_LINE="${YELLOW}\$${COST_FMT}${RESET}"
    fi
fi
if [ -n "$TODAY_SEG" ]; then
    TODAY_LINE="${TODAY_LINE:+$TODAY_LINE$SEP}${BOLD}${YELLOW}${TODAY_SEG}${RESET}"
fi

# Line 2 carries the VARIABLE-LENGTH names (dir / branch / worktree), which can be
# arbitrarily long per project -- keeping them off line 1 stops it from wrapping.
LINE2=
[ -n "$DIRBASE" ] && LINE2="${BOLD}${DIRBASE}${RESET}"
[ -n "$BRANCH" ] && LINE2="${LINE2:+$LINE2$SEP}${MAGENTA}${BRANCH}${RESET}"
if [ -n "$WORKTREE" ] && [ "$WORKTREE" != "$BRANCH" ] && [ "$WORKTREE" != "$DIRBASE" ]; then
  LINE2="${LINE2:+$LINE2$SEP}${DIM}${WORKTREE}${RESET}"
fi
if [ "$ADD" != "0" ] || [ "$DEL" != "0" ]; then
  LINE2="${LINE2:+$LINE2$SEP}${GREEN}+${ADD}${RESET}${DIM}/${RESET}${RED}-${DEL}${RESET}"
fi

printf '%s\n' "$LINE1"
[ -n "$TODAY_LINE" ] && printf '%s\n' "$TODAY_LINE"
[ -n "$LINE2" ] && printf '%s\n' "$LINE2"
exit 0
